 protected void onResume(){super.onResume();resumed=true;GuardService.appVisible=true;scene.resume();refreshSetup();worker.execute(()->{Map<String,Long>u;try{u=Device.usage(this);}catch(Exception e){u=Collections.emptyMap();}Map<String,Long>result=u;runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())usage=result;});});Warnings.schedule(this);if(bypassRequested){bypassRequested=false;bypass(getIntent().getBooleanExtra("strict",false));}}
 protected void onPause(){resumed=false;scene.pause();GuardService.appVisible=false;super.onPause();}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);bypassRequested=i.getBooleanExtra("bypass",false);if(resumed&&bypassRequested){bypassRequested=false;bypass(i.getBooleanExtra("strict",false));}}
 protected void onSaveInstanceState(Bundle b){b.putString("flow",flow.checkpoint());b.putString("page",scene.currentPanel()==null?"":page);b.putString("editor",editorKind);b.putString("key",editorKey);b.putString("draft",encoded(config));b.putBoolean("reduced",draftReduced);b.putBoolean("companion",draftCompanion);b.putBoolean("wander",draftWander);b.putInt("size",draftSize);b.putBoolean("reset",resetPosition);if(scene.currentPanel()!=null&&!editorKind.equals("bypass"))b.putBundle("form",RoomFormState.capture(scene.currentPanel().content()));super.onSaveInstanceState(b);}
