 private String encoded(Rules.Config value){try{return Store.encode(value);}catch(Exception e){return "";}}
 private void loadPresentation(){var presentation=getSharedPreferences("presentation",0);var pocket=getSharedPreferences("pocket_yuki",0);draftReduced=presentation.getBoolean("reduce_motion",false);draftCompanion=pocket.getBoolean("enabled",true);draftWander=pocket.getBoolean("wander",true);draftSize=CompanionSize.clamp(pocket.getInt("size_dp",CompanionSize.DEFAULT));resetPosition=false;}
 private void savePresentation(){
  var presentation=getSharedPreferences("presentation",0);var pocket=getSharedPreferences("pocket_yuki",0);
  if(presentation.getBoolean("reduce_motion",false)!=draftReduced&&!presentation.edit().putBoolean("reduce_motion",draftReduced).commit())throw new IllegalStateException("Could not save motion preference. Please retry.");
  if((pocket.getBoolean("enabled",true)!=draftCompanion||pocket.getBoolean("wander",true)!=draftWander||pocket.getInt("size_dp",CompanionSize.DEFAULT)!=draftSize||resetPosition)){
   var changes=pocket.edit().putBoolean("enabled",draftCompanion).putBoolean("wander",draftWander).putInt("size_dp",draftSize);if(resetPosition)changes.remove("x").remove("y");if(!changes.commit())throw new IllegalStateException("Could not save companion preferences. Please retry.");if(resetPosition){GuardService.resetCompanionPosition();resetPosition=false;}
  }scene.resume();
 }
 private void restorePanel(){if(page.isEmpty()){if(flow.step()==RoomDialogue.Step.PANEL)flow.returnToDialogue("I’m here, Darling. ♡");scene.updateDialogue();return;}String kind=editorKind,key=editorKey,route=page;openPage(route);switch(kind){case "app"->editApp(key);case "domain"->editDomain(key.isEmpty()?null:key);case "schedule"->editSchedule(config.schedules.stream().filter(v->v.id.equals(key)).findFirst().orElse(null));case "ai"->aiDestination();case "friction"->bypassPreferences();case "removeApp"->removeApp(key);case "removeDomain"->removeDomain(key);case "removeSchedule"->removeSchedule(key);case "picker"->chooseInstalled();case "bypass"->bypass(false);default->{}}if(restoration!=null&&scene.currentPanel()!=null&&!kind.equals("bypass")&&!kind.equals("picker")&&!kind.equals("removal"))RoomFormState.restore(scene.currentPanel().content(),restoration.getBundle("form"));if(!kind.equals("picker"))restoration=null;}
 private void refreshSetup(){if(guardLabel!=null)guardLabel.setText("Status: "+(GuardService.connected?"Connected":Device.accessibilityEnabled(this)?"Enabled; waiting for Android":"Disabled"));if(usageLabel!=null)usageLabel.setText(Device.usageAllowed(this)?"Usage access granted":"Usage access not granted");if(notificationLabel!=null)notificationLabel.setText(getSystemService(NotificationManager.class).areNotificationsEnabled()?"Notifications available":"Notifications disabled");}
