 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 private void save(){if(!store.error.isEmpty())throw new IllegalStateException(store.error);String next=encoded(config);try{Store.decode(next);}catch(Exception e){throw new IllegalArgumentException("Check the rule settings before saving.");}if(!next.equals(savedConfig)){if(!store.save(config))throw new IllegalStateException(store.error);savedConfig=next;Warnings.schedule(this);}}
 private void attempt(Runnable action){String before=encoded(config),savedBefore=savedConfig;try{action.run();}catch(Exception e){if(savedConfig.equals(savedBefore))try{config=Store.decode(before);}catch(Exception ignored){}if(scene.currentPanel()!=null)scene.currentPanel().reportError(e);else toast(e.getMessage());}}
 private void discard(){config=store.load();savedConfig=encoded(config);loadPresentation();if(scene.currentPanel()!=null)scene.currentPanel().discard();page="";editorKind="";}
 private void openPage(String destination){
  page=destination;editorKind="";editorKey="";guardLabel=null;usageLabel=null;notificationLabel=null;body=form();
  switch(destination){case "Protected Apps","Apps"->apps();case "Sites","Websites"->websites();case "Plans","Schedules"->schedules();case "Settings"->settings();default->talk();}
  if(!store.error.isEmpty())Ui.text(body,store.error,15,Ui.BLUE);
  Ui.text(body,"× saves changes and returns to our conversation.",13,Ui.MUTED);Ui.secondary(body,"Discard unsaved changes",this::discard);
  scene.createPanel(destination,body,()->{save();savePresentation();page="";editorKind="";},true).show();
 }
 private void talk(){
  Ui.text(body,"A little time together",24,Ui.WHITE);Ui.text(body,"I’m glad you’re here, Darling. What’s on your mind? ♡",17,Ui.BLUE);
  Ui.secondary(body,"A quiet moment",()->{page="";editorKind="";scene.reply("You don’t have to fill every quiet moment. Settle in with me for a little while. ♡");});
  TextView boundaryStatus=Ui.text(body,"",15,Ui.MUTED);boundaryStatus.setVisibility(View.GONE);
  Ui.secondary(body,"How are my boundaries doing?",()->{String state=!config.enabled?"Protection is paused.":store.bypassActive()?"Your emergency break is active.":GuardService.connected?"Your guard is connected.":"Your guard needs setup before it can protect your boundaries.";long total=0;for(String pkg:config.apps.keySet())if(!config.apps.get(pkg).exempt)total+=usage.getOrDefault(pkg,0L);boundaryStatus.setText(state+"\n"+config.apps.size()+" configured apps · "+config.domains.size()+" permanent domains · "+config.schedules.size()+" plans\n"+(Device.usageAllowed(this)?total/60000+" minutes across protected apps today":"Daily usage needs Usage access."));boundaryStatus.setVisibility(View.VISIBLE);});
  Ui.secondary(body,"Settings & setup",()->openPage("Settings"));
  Ui.secondary(body,"Open AI chat",()->attempt(()->{save();savePresentation();Device.talk(this);}));Ui.text(body,"Room dialogue is local. Open AI chat launches your configured app.",13,Ui.MUTED);
 }
 private void apps(){
  Ui.text(body,"Protected Apps",28,Ui.WHITE);Ui.text(body,"Set allowances, restrictions and exemptions. System essentials stay available.",15,Ui.MUTED);Ui.button(body,"Browse installed apps",this::chooseInstalled);if(config.apps.isEmpty())Ui.text(body,"Add your AI apps and choose Always Allowed to exempt them.",16,Ui.WHITE);
  for(Map.Entry<String,Rules.AppRule>e:config.apps.entrySet()){String pkg=e.getKey();Rules.AppRule a=e.getValue();LinearLayout card=Ui.card(body);try{ImageView icon=new ImageView(this);icon.setImageDrawable(getPackageManager().getApplicationIcon(pkg));icon.setContentDescription(a.name+" icon");card.addView(icon,new LinearLayout.LayoutParams(Ui.dp(this,40),Ui.dp(this,40)));}catch(Exception ignored){}Ui.text(card,a.name,20,Ui.WHITE);Ui.text(card,a.exempt?"Always Allowed":a.blocked?"Always restricted":a.minutes<0?"Schedules only":a.minutes+" min/day",15,Ui.BLUE);if(!a.exempt)Ui.text(card,Device.usageAllowed(this)?"Today: "+usage.getOrDefault(pkg,0L)/60000+" min":"Usage access needed for today’s measurement",13,Ui.MUTED);List<String>names=new ArrayList<>();for(Rules.Schedule s:config.schedules)if(s.apps.contains(pkg))names.add(s.name);Ui.text(card,"Schedules: "+(names.isEmpty()?"none":String.join(", ",names)),13,Ui.MUTED);Ui.secondary(card,"Configure",()->editApp(pkg));}
 }
 private void chooseInstalled(){
  editorKind="picker";editorKey="";LinearLayout loading=form();Ui.text(loading,"Finding installed apps…",17,Ui.WHITE);RoomPanel picker=scene.createPanel("Choose an app",loading,()->{save();savePresentation();},true);picker.show();
  worker.execute(()->{
   Set<String>safe=Device.safe(this);Map<String,String>found=new TreeMap<>();for(ResolveInfo r:getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0))if(!safe.contains(r.activityInfo.packageName))found.put(r.activityInfo.packageName,r.loadLabel(getPackageManager()).toString());List<String>packages=new ArrayList<>(found.keySet());packages.sort(Comparator.comparing(found::get,String.CASE_INSENSITIVE_ORDER));
   runOnUiThread(()->{if(isFinishing()||isDestroyed()||!picker.isShowing())return;LinearLayout panel=form();EditText search=Ui.field(panel,"Search apps","",false);LinearLayout results=Ui.column(this);panel.addView(results);picker.setContent(panel);
    Runnable refresh=()->{String q=search.getText().toString().toLowerCase(Locale.ROOT);results.removeAllViews();int matches=0;for(String pkg:packages)if(found.get(pkg).toLowerCase(Locale.ROOT).contains(q)||pkg.contains(q)){Ui.secondary(results,found.get(pkg),()->editApp(pkg));matches++;}if(matches==0)Ui.text(results,"No matching apps.",15,Ui.MUTED);};refresh.run();search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){refresh.run();}public void afterTextChanged(android.text.Editable e){}});if(restoration!=null){RoomFormState.restore(panel,restoration.getBundle("form"));restoration=null;}
   });
  });
 }
