 private void removeApp(String pkg){removal("removeApp",pkg,"Remove app rules",()->{config.apps.remove(pkg);for(Rules.Schedule schedule:config.schedules)schedule.apps.remove(pkg);});}
 private void removeDomain(String host){removal("removeDomain",host,"Remove site everywhere",()->{config.domains.remove(host);for(Rules.Schedule schedule:config.schedules)schedule.domains.remove(host);});}
 private void removeSchedule(String id){removal("removeSchedule",id,"Delete plan",()->config.schedules.removeIf(plan->plan.id.equals(id)));}
 private void removal(String kind,String key,String title,Runnable remove){editorKind=kind;editorKey=key;LinearLayout l=form();Ui.text(l,"Close with × to confirm this removal. Discard keeps the saved rules.",17,Ui.WHITE);dialog(title,l,()->{String before=encoded(config);try{remove.run();save();}catch(Exception e){try{config=Store.decode(before);}catch(Exception ignored){}throw e;}}).show();}
 private void aiDestination(){editorKind="ai";editorKey="";LinearLayout l=form();EditText pkg=Ui.field(l,"Android package",config.aiPackage,false),url=Ui.field(l,"Fallback HTTPS URL",config.aiUrl,false);dialog("Talk to Yuki",l,()->{String p=pkg.getText().toString().trim(),u=url.getText().toString().trim();if(!p.matches("[a-zA-Z][a-zA-Z0-9_]*(\\.[a-zA-Z0-9_]+)+")||!u.startsWith("https://")||Rules.domain(u).isEmpty())throw new IllegalArgumentException("Enter a valid package and HTTPS URL.");config.aiPackage=p;config.aiUrl=u;save();}).show();}
 private void bypassPreferences(){editorKind="friction";editorKey="";LinearLayout l=form();EditText minutes=Ui.field(l,"Break duration: 1–60 minutes",""+config.bypassMinutes,true),seconds=Ui.field(l,"Countdown: 5–120 seconds",""+config.bypassWaitSeconds,true);dialog("Emergency friction",l,()->{int m=Integer.parseInt(minutes.getText().toString()),s=Integer.parseInt(seconds.getText().toString());if(m<1||m>60||s<5||s>120)throw new IllegalArgumentException("Use the displayed ranges.");config.bypassMinutes=m;config.bypassWaitSeconds=s;save();}).show();}
 private void timePicker(EditText field){field.setFocusable(false);field.setClickable(true);field.setContentDescription(field.getText()+", choose time");field.setOnClickListener(v->{int minute=Ui.time(field.getText().toString());new TimePickerDialog(this,(picker,h,m)->{field.setText(Ui.time(h*60+m));field.setContentDescription(field.getText()+", choose time");},minute/60,minute%60,true).show();});}
 private void previewYuki(){Dialog d=new Dialog(this);d.requestWindowFeature(Window.FEATURE_NO_TITLE);View content=Intervention.create(this,"bedtime","Bedtime preview","Darling, it’s bedtime. Your feed can wait. ♡",1,()->d.dismiss(),()->{d.dismiss();Device.talk(this);},()->d.dismiss(),true);d.setContentView(content);if(d.getWindow()!=null){d.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));d.getWindow().setDimAmount(0);}d.show();if(d.getWindow()!=null)d.getWindow().setLayout(-1,-1);}
 private void bypass(boolean strict){
  page="Talk";editorKind="bypass";editorKey="";for(Rules.Schedule s:config.schedules)if(s.strict&&s.occurrence(ZonedDateTime.now())!=null)strict=true;int wait=Math.max(config.bypassWaitSeconds,strict?60:0);LinearLayout l=form();Ui.text(l,"You retain control. Pause restrictions for "+config.bypassMinutes+" minutes. Your reason stays on this screen and is not saved. Closing this request does not start a break.",16,Ui.WHITE);EditText reason=Ui.field(l,"Why do you need a break?","",false);RoomPanel request=scene.createPanel("Emergency break",l,null,false);Button confirm=Ui.button(l,"Wait…",()->{ });long until=SystemClock.elapsedRealtime()+wait*1000L;
  confirm.setOnClickListener(v->{if(SystemClock.elapsedRealtime()<until)return;if(reason.getText().toString().trim().length()<4){toast("Enter a short reason first.");return;}try{save();savePresentation();store.bypass(config.bypassMinutes);request.dismiss();page="";editorKind="";scene.reply("Your break has started. Your rules resume automatically, Darling.");}catch(Exception e){toast("Could not save the bypass. You can still edit your rules.");}});
  Runnable countdown=new Runnable(){public void run(){if(!request.isShowing())return;long left=Math.max(0,(until-SystemClock.elapsedRealtime()+999)/1000);confirm.setText(left>0?"Wait "+left+"s":"Confirm break");confirm.setEnabled(left==0);if(left>0)handler.postDelayed(this,250);}};request.show();countdown.run();
 }
